OWW={}; OWW.f=CreateFrame("Frame","OWWATCH",UIParent); OWW.g=GameTooltip:IsShown(); OWW.n=""; OWW.f:SetScript("OnUpdate",function() local m=GetMouseFocus(); local n="nil"; if m and m.GetName then n=tostring(m:GetName()) end; local g=GameTooltip:IsShown(); if n~=OWW.n or g~=OWW.g then OWW.n=n; OWW.g=g; DEFAULT_CHAT_FRAME:AddMessage("t="..string.format("%.1f",GetTime()).." GT="..tostring(g).." mf="..n) end end); DEFAULT_CHAT_FRAME:AddMessage("OWWATCH2-OK")